// A pre-rendered still of the landing scene (§6.2.6). Generated by scripts/render-loop-stills.ts from the real scene
// at /dev/loop and written to public/landing/. Decorative: alt="" (the text around it carries the meaning).
// Served as static files with explicit size (no CLS) and without the runtime image optimiser (no sharp on the
// server, CONFLICTS C-25).

export const STILL_SIZE = 1200;
export const BEATS = [0, 1, 2, 3, 4, 5, 6, 7] as const;
export type Beat = (typeof BEATS)[number];

export function stillSrc(beat: number, size: 600 | 1200 = 1200): string {
  return `/landing/loop-beat-${beat}${size === 600 ? "-600" : ""}.webp`;
}

export function LoopStill({ beat, priority = false, className, size = 1200 }: { beat: number; priority?: boolean; className?: string; size?: 600 | 1200 }) {
  return (
    <img
      src={stillSrc(beat, size)}
      srcSet={`${stillSrc(beat, 600)} 600w, ${stillSrc(beat, 1200)} 1200w`}
      sizes="(min-width: 1024px) 50vw, 100vw"
      width={size}
      height={size}
      alt=""
      decoding="async"
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : "auto"}
      className={className}
      data-beat-still={beat}
    />
  );
}
